import rawManifest from './sfx-manifest.json';

/** Every SFX family generated by scripts/kit_make_sfx.py. A cue "name" is a family name. */
export const SFX_FAMILIES = [
  'tap',
  'tick',
  'pop',
  'whoosh-soft',
  'whoosh-fast',
  'swipe',
  'slide',
  'rise',
  'fall',
  'chime-success',
  'soft-warn',
  'number-tick',
  'impact-soft',
] as const;

/** Name of an SFX family (and of a cue). */
export type SfxFamily = (typeof SFX_FAMILIES)[number];

/** Variants per family (1-based). */
export const SFX_VARIANTS = 3;

/** One generated sound file, as recorded in manifest.json. */
export interface SfxInfo {
  /** e.g. "tap-2", or "tick-n04" for a pitched file */
  name: string;
  family: SfxFamily;
  /** 1..SFX_VARIANTS; 0 for pitched files */
  variant: number;
  /** Path for staticFile(), e.g. "kit/sfx/tap-2.wav" */
  file: string;
  /** Pre-panned stereo versions that exist: "L" -> `tap-2@L.wav`, "R" -> `tap-2@R.wav`. */
  pan: ('L' | 'R')[];
  /** Seconds. */
  duration: number;
  peakDb: number;
  /** Seconds from file start to the loudest sample (used to align a sound's peak to a motion event). */
  peakTime: number;
  /** RMS (dBFS) while the sound is sounding. */
  rmsDb: number;
  /** K-weighted whole-file loudness estimate. */
  lufs: number;
}

/** Families that also come as a set of pitched files, one per note of the kit's key (see scripts/sfx_key.py). */
export const PITCHED_FAMILIES = ['number-tick', 'tick', 'pop'] as const;

/** Name of a family with pitched files. */
export type PitchedFamily = (typeof PITCHED_FAMILIES)[number];

/** Notes in each pitched set, ascending along D major pentatonic. */
export const PITCHED_NOTES = 12;

/** One pitched sound file. */
export interface PitchedSfxInfo extends SfxInfo {
  family: PitchedFamily;
  /** 0 (lowest) .. PITCHED_NOTES - 1 (highest). */
  noteIndex: number;
  /** Note name, e.g. "E6". */
  note: string;
  /** MIDI note number. */
  midi: number;
}

/**
 * Whether a family has pitched files.
 * @example isPitchedFamily('pop') // true
 */
export const isPitchedFamily = (family: string): family is PitchedFamily => (PITCHED_FAMILIES as readonly string[]).includes(family);

const SOUNDS = (rawManifest as {sounds: SfxInfo[]}).sounds;
const PITCHED = (rawManifest as unknown as {pitched: PitchedSfxInfo[]}).pitched;

/**
 * Manifest entry for a family variant.
 * @example sfxInfo('chime-success', 2).duration // 1.05
 */
export const sfxInfo = (family: SfxFamily, variant: number): SfxInfo => {
  const hit = SOUNDS.find((s) => s.family === family && s.variant === variant);
  if (!hit) throw new Error(`kit/audio: no sound "${family}" variant ${variant} in sfx-manifest.json (re-run scripts/kit_make_sfx.py)`);
  return hit;
};

/** All variant entries (pitched files are listed by {@link allPitchedSfx}). */
export const allSfx = (): readonly SfxInfo[] => SOUNDS;

/**
 * Manifest entry for one note of a pitched set.
 * @example pitchedInfo('number-tick', 0).note // "C6"
 */
export const pitchedInfo = (family: PitchedFamily, noteIndex: number): PitchedSfxInfo => {
  const hit = PITCHED.find((s) => s.family === family && s.noteIndex === noteIndex);
  if (!hit) throw new Error(`kit/audio: no pitched sound "${family}" note ${noteIndex} in sfx-manifest.json (re-run scripts/kit_make_sfx.py)`);
  return hit;
};

/** All pitched manifest entries. */
export const allPitchedSfx = (): readonly PitchedSfxInfo[] => PITCHED;

/**
 * Note index for a data value: `min` gives the lowest note, `max` the highest, linearly in between; values outside the
 * range are clamped. An empty range (`min === max`) gives the lowest note. For a falling scale, swap the sign of all three.
 * @example cue('pop', 1.2, {note: noteForValue(72, 0, 100)}) // 8
 */
export const noteForValue = (value: number, min: number, max: number): number => valueToNoteIndex(value, {min, max});

/** Same mapping with a range object: `min` -> note 0, `max` -> note 11, linear, clamped; `min === max` -> 0; throws on NaN or max < min. */
export const valueToNoteIndex = (value: number, range: {min: number; max: number}): number => {
  const {min, max} = range;
  if (![value, min, max].every(Number.isFinite) || max < min) throw new RangeError(`kit/audio: valueToNoteIndex(${value}, {min: ${min}, max: ${max}}) needs finite numbers and max >= min`);
  if (max === min) return 0;
  const x = Math.min(1, Math.max(0, (value - min) / (max - min)));
  return Math.round(x * (PITCHED_NOTES - 1));
};

/** Default level and polyphony priority per family. Files are all normalised to -3 dBFS peak; these set the mix. */
export interface FamilyDefaults {
  /** Default playback gain in dB relative to the normalised file (<= 0). */
  gainDb: number;
  /** Higher survives when more than `maxSimultaneous` sounds overlap. */
  priority: number;
}

/**
 * Per-family mix defaults. Peak-normalised files differ a lot in perceived level (a 30 ms tick vs a sub-bass thud), so
 * the cue system applies these on top; a cue's own `gain` multiplies them.
 */
export const FAMILY_DEFAULTS: Record<SfxFamily, FamilyDefaults> = {
  tap: {gainDb: -6, priority: 3},
  tick: {gainDb: -12, priority: 2},
  pop: {gainDb: -9, priority: 3},
  'whoosh-soft': {gainDb: -9, priority: 2},
  'whoosh-fast': {gainDb: -9, priority: 2},
  swipe: {gainDb: -9, priority: 2},
  slide: {gainDb: -9, priority: 2},
  rise: {gainDb: -14, priority: 3},
  fall: {gainDb: -14, priority: 3},
  'chime-success': {gainDb: -9, priority: 5},
  'soft-warn': {gainDb: -9, priority: 5},
  'number-tick': {gainDb: -22, priority: 1},
  'impact-soft': {gainDb: -8, priority: 4},
};

/** dB -> linear amplitude. @example dbToGain(-6) // 0.501 */
export const dbToGain = (db: number): number => Math.pow(10, db / 20);

/** Linear amplitude -> dB (floored at -120). @example gainToDb(0.5) // -6.02 */
export const gainToDb = (g: number): number => 20 * Math.log10(Math.max(g, 1e-6));
